function M({registerIndicator:H,nulls:r}){H({id:"oa-accbands",name:"Acceleration Bands (ACCBANDS)",category:"Channels",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:20,min:1,max:5e3,step:1},{key:"factor",type:"number",label:"Factor",default:2,min:.001,max:100,step:.1}],plots:[{key:"middle",type:"line",title:"Middle",style:{color:"#ffeb3b",lineWidth:2}},{key:"upper",type:"line",title:"Upper",style:{color:"#ffeb3b",lineWidth:2}},{key:"lower",type:"line",title:"Lower",style:{color:"#ffeb3b",lineWidth:2}}],fills:[{between:["upper","lower"],colorUp:"#2962ff",colorDown:"#2962ff",opacity:.1}],calc(m,b){const l=Math.max(1,Math.floor(Number(b.period)||20)),L=Math.max(.001,Number(b.factor)||2),n=m.length,d=new Array(n).fill(NaN),p=new Array(n).fill(NaN),N=new Array(n).fill(NaN),y=new Array(l).fill(NaN),h=new Array(l).fill(NaN),w=new Array(l).fill(NaN);let e=0,t=0,c=0,a=0,s=0;for(let o=0;o<n;o++){const A=y[e];Number.isFinite(A)&&(c-=A,a-=h[e],s-=w[e],t-=1);const i=m[o],g=Number.isFinite(i.high)?Number(i.high):0,F=Number.isFinite(i.low)?Number(i.low):0,C=Number.isFinite(i.close)?Number(i.close):0;if(c+=g,a+=F,s+=C,t+=1,y[e]=g,h[e]=F,w[e]=C,e=(e+1)%l,t<=0)continue;const u=c/t,f=a/t,k=s/t;if(!Number.isFinite(u)||!Number.isFinite(f)||!Number.isFinite(k))continue;const x=(u-f)*L;d[o]=k,p[o]=u+x,N[o]=f-x}return{middle:r(d),upper:r(p),lower:r(N)}}})}export{M as default};
